/* The only exports of libwolwebengine.so.1 (ABI 1). Append-only within a major: a new version node
 * per addition, so a host built for 1.0 still loads (WWE_1.1 is the host channel, ADR 0048). */
WOLWEBENGINE_1 {
  global:
    wwe_abi_version;
    wwe_engine_version;
    wwe_engine_new;
    wwe_engine_free;
    wwe_engine_spin;
    wwe_view_new;
    wwe_view_free;
    wwe_view_state;
    wwe_view_resize;
    wwe_view_input;
    wwe_view_focus;
    wwe_view_visible;
    wwe_view_theme;
    wwe_view_screenshot;
    wwe_image_free;
    wwe_run_content_process;
  local:
    *;
};

WWE_1.1 {
  global:
    wwe_engine_set_host_channel;
    wwe_view_post_message;
} WOLWEBENGINE_1;

/* 1.2 is wwe_engine_set_scheme (wave3/federate); 1.3 does not depend on it. */
WWE_1.3 {
  global:
    wwe_view_present;
} WWE_1.1;
